import React, { useCallback, useMemo, useState } from "react";

/**
 * USStateMap
 *
 * Interactive, dark-theme-compatible SVG map of the United States
 * (Albers USA projection, 959x593 viewBox — Alaska and Hawaii inset
 * bottom-left in the standard layout).
 *
 * Path geometry is derived from the US Census Bureau cartographic
 * boundary files (via the "us-atlas" TopoJSON package / d3-geo
 * geoAlbersUsa projection), so every state outline is real, accurate
 * geography — not a placeholder.
 */

export interface USStateMapProps {
  /** Called with the 2-letter state code on hover, or null on mouse leave. */
  onStateHover: (stateCode: string | null) => void;
  /** Called with the 2-letter state code when a state is clicked. */
  onStateClick: (stateCode: string) => void;
  /** Currently selected state code (gets cyan stroke/glow), or null. */
  selectedState: string | null;
  /** Returns the fill color for a given state code. */
  getStateFill: (stateCode: string) => string;
  /** Optional: hide the abbreviation labels entirely. Defaults to false. */
  hideLabels?: boolean;
  /** Optional: extra className for the wrapping <svg>. */
  className?: string;
}

interface StateDatum {
  name: string;
  d: string;
}

